def sudoku_valid(board):
    if not isinstance(board, list) or len(board) != 9:
        raise ValueError("Board must be 9x9")
    for row in board:
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError("Board must be 9x9")
        for v in row:
            if not isinstance(v, int) or v < 0 or v > 9:
                raise ValueError("Values must be integers 0-9")

    def has_dup(vals):
        seen = set()
        for v in vals:
            if v != 0:
                if v in seen:
                    return True
                seen.add(v)
        return False

    for r in range(9):
        if has_dup(board[r]):
            return False
    for c in range(9):
        if has_dup(board[r][c] for r in range(9)):
            return False
    for br in range(0, 9, 3):
        for bc in range(0, 9, 3):
            box = [board[br+i][bc+j] for i in range(3) for j in range(3)]
            if has_dup(box):
                return False
    return True
